Q: How To Avoid Circular Dependency Without Container Query? A: <p>What about a grid configuration</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-css lang-css prettyprint-override"><code>body {
  --ratio: 3 / 2;
  margin: 0;
}

#card {
  height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr;
  margin: auto;
  width: fit-content;
}

#innermost {
  background-color: pink;
  aspect-ratio: var(--ratio);
  height: 60vh; /* 100% - the min_height you want for bottom panel */
  max-height: calc(100vw/(var(--ratio)));
}

#bottom-panel {
  background-color: rgb(110, 110, 110);
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div id="card"&gt;
  &lt;div id="top-panel"&gt;
    &lt;div id="innermost"&gt;&lt;/div&gt;
  &lt;/div&gt;
  &lt;div id="bottom-panel"&gt;&lt;/div&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>

Q: Get first day of every month between two dates A: <p>Alternative: Plain Old JS, no library.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>console.log(
  getFirstOfMonthDatesBetween(
    new Date("2025-10-10"), 
    new Date("2026-01-02") )
);

function getFirstOfMonthDatesBetween(start, end) {
  let runningDate = new Date(
    Date.UTC(start.getFullYear(), start.getMonth() + 1, 1) );
  const dates = [start, runningDate, end];

  while ( runningDate &lt; end ) {
    runningDate = new Date(Date.UTC(
      runningDate.getFullYear(), runningDate.getMonth() + 1, 1) );
    runningDate &lt; end &amp;&amp; dates.splice(-1, 0, runningDate);
  }

  return dates;
}</code></pre>
